function digitSquareSum(n){ var s=0; n=Math.abs(Math.floor(n)); while(n>0){ var d=n%10; s+=d*d; n=Math.floor(n/10);} return s; }
function isHappy(n){
  n=Math.floor(Math.abs(+n));
  if(isNaN(n)) return {error:'请输入非负整数'};
  if(n===0) return {value:false, isHappy:false, steps:0};
  var seen={}, cur=n, steps=0;
  while(cur!==1 && !seen[cur]){ seen[cur]=1; cur=digitSquareSum(cur); steps++; if(steps>1000) break; }
  var h=cur===1;
  return {value:h, isHappy:h, steps:steps};
}
var EXPORTS={isHappy:isHappy};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.HappyForgePure = EXPORTS; }
